import{_ as n,o as t,c as i,a2 as p}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"RH InkTank Ceph Day Sessions Mario Blandini HGST","description":"","frontmatter":{"title":"RH InkTank Ceph Day Sessions Mario Blandini HGST","date":"2014-07-25T00:00:00.000Z","updated":"2014-07-25T00:00:00.000Z","tags":["Ceph","HGST","Open Ethernet Drive Architecture","Software","defined Storage","OpenStack"],"categories":["会议纪要","存储技术"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/RH_InkTank_Ceph_Day_Sessions_Mario_Blandini_HGST.md","filePath":"posts/2014/RH_InkTank_Ceph_Day_Sessions_Mario_Blandini_HGST.md","lastUpdated":1780459816000}'),r={name:"posts/2014/RH_InkTank_Ceph_Day_Sessions_Mario_Blandini_HGST.md"};function s(a,e,o,l,_,S){return t(),i("div",null,[...e[0]||(e[0]=[p('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>会议地点</strong>： 未提及</p><p><strong>参会人员</strong>： HGST代表Mario Blandini、Karanvir Singh以及Ceph社区成员</p><p><strong>会议主题</strong>： HGST的开放以太网驱动架构及其在Ceph中的应用</p><p><strong>会议内容</strong>：</p><p><strong>一、HGST公司介绍</strong></p><p>HGST是一家专注于存储解决方案的硬件公司，产品包括硬盘驱动器、固态硬盘、PCIe闪存和软件。公司认为，随着数据量的不断增长，需要新的技术创新来满足存储需求。</p><p><strong>二、开放以太网驱动架构</strong></p><p>HGST提出了开放以太网驱动架构，旨在将数据存储服务移动到更靠近存储介质的位置。该架构具有以下特点：</p><ul><li>开放：采用开源软件和硬件，以支持创新和可扩展性。</li><li>以太网：利用以太网连接，简化管理和监控。</li><li>驱动：基于硬盘驱动器，提供高性能和可扩展性。</li><li>架构：作为软件定义数据中心的基础构件。</li></ul><p><strong>三、硬件设计</strong></p><p>HGST展示了其参考设计方案，包括：</p><ul><li>3.5英寸硬盘驱动器，具有SAS连接器和内置以太网。</li><li>60个硬盘驱动器的机架式服务器。</li><li>集成交换机。</li><li>10千兆以太网端口。</li></ul><p><strong>四、软件支持</strong></p><p>HGST的开放以太网驱动架构支持Ceph、Gluster和OpenStack等开源软件。HGST展示了Ceph集群和Gluster集群的运行情况，并进行了数据传输演示。</p><p><strong>五、未来展望</strong></p><p>HGST计划进一步优化其开放以太网驱动架构，以提高性能和可扩展性。HGST将积极与Ceph社区合作，共同推动开源存储技术的发展。</p><p><strong>六、行动计划</strong></p><p>HGST将继续与Ceph社区合作，共同推动开源存储技术的发展。 HGST将探索将开放以太网驱动架构应用于更多场景。 HGST将积极寻求与软件开发商合作，共同开发基于该架构的创新解决方案。</p><p><strong>七、关键术语</strong></p><ul><li>开放以太网驱动架构（Open Ethernet Drive Architecture）</li><li>软件定义存储（Software-defined Storage）</li><li>Ceph</li><li>Gluster</li><li>OpenStack</li></ul><p><strong>八、总结</strong></p><p>HGST的开放以太网驱动架构为Ceph等开源存储解决方案提供了一种新的解决方案，有助于提高性能、可扩展性和可管理性。该架构具有广阔的应用前景，值得Ceph社区关注。</p>',24)])])}const d=n(r,[["render",s]]);export{g as __pageData,d as default};
